<?php
namespace qqworld_collector\module\pseudo_original; use qqworld_collector\lib; class random_paragraphs extends lib { var $log_id = 'pseudo-original'; public function init() { if (isset($_POST['enabled_random_paragraph'])) $this->options->qc_pseudo_original_enabled_random_paragraphs = $_POST['enabled_random_paragraph']; if ($this->options->qc_pseudo_original_enabled_random_paragraphs) { add_action( 'wp_insert_post', array($this, 'wp_insert_post'), 10, 3 ); add_action( 'wp_ajax_qqworld-collector-pseudo-original-scan-random-paragraphs-all', array($this, 'scan_random_paragraphs_all') ); add_action( 'wp_ajax_nopriv_qqworld-collector-pseudo-original-scan-random-paragraphs-all', array($this, 'scan_random_paragraphs_all') ); add_action( 'qqworld-collector-settings-meta-box', array($this, 'setting_meta_box') ); } } public function random_paragraphs($item, $values) { if ($values['back'] || $values['front']) { $pattern = '/<\!\-\-random\-paragraphs\-\->[\s\S]*?<\!\-\-\/random\-paragraphs\-\->/i'; if (preg_match($pattern, $item)) { if (isset($_POST['update-random-paragraph']) && !filter_var($_POST['update-random-paragraph'], FILTER_VALIDATE_BOOLEAN)) return $item; else $item = preg_replace($pattern, '', $item); } foreach ($values as $position => $value) { $value = "<!--random-paragraphs-->\r\n" . $value . "\r\n<!--/random-paragraphs-->"; switch ($position) { case 'front': $item = $value . $item; break; case 'back': $item = $item . $value; break; } } } return $item; } public function the_category_list($categories, $post_id) { return array_slice($categories, 0, 5, true); } public function get_the_terms($terms, $post_id, $taxonomy) { return array_slice($terms, 0, 5, true); } public function variable_filter($post_content, $post, $post_ID) { $patterns = array(); $replacements = array(); if (strstr($post_content, '{var:post_link}') !== false) { $patterns[] = '{var:post_link}'; $replacements[] = get_permalink($post_ID); } if (strstr($post_content, '{var:post_title}') !== false) { $patterns[] = '{var:post_title}'; $replacements[] = $post->post_title; } if (strstr($post_content, '{var:post_excerpt}') !== false) { $patterns[] = '{var:post_excerpt}'; $replacements[] = $post->post_excerpt; } add_filter( 'the_category_list', array($this, 'the_category_list'), 10, 2 ); add_filter( 'get_the_terms', array($this, 'get_the_terms'), 10, 3 ); if (strstr($post_content, '{var:category}') !== false) { $patterns[] = '{var:category}'; $replacements[] = get_the_category_list(_x(', ', 'term', $this->text_domain), '', $post_ID); } if (strstr($post_content, '{var:post_tag}') !== false) { $patterns[] = '{var:post_tag}'; $replacements[] = get_the_tag_list( '', _x(', ', 'term', $this->text_domain), '', $post_ID ); } remove_filter( 'the_category_list', array($this, 'the_category_list'), 10, 2 ); remove_filter( 'get_the_terms', array($this, 'get_the_terms'), 10, 3 ); if (preg_match_all('/\{var:post_meta:(.*?)\}/i', $post_content, $matches)) { foreach ($matches[1] as $index => $meta_key) { $patterns[] = $matches[0][$index]; if (preg_match('/\[.*\]/i', $meta_key, $match)) { $meta_key = str_replace($match[0], '', $meta_key); $replacement = get_post_meta( $post_ID, $meta_key, true ); eval('$replacement = $replacement'.$match[0].';'); } else { $replacement = get_post_meta( $post_ID, $meta_key, true ); } $replacements[] = $replacement; } } if (preg_match_all('/\{h:(.*?)\}/i', $post_content, $matches)) { foreach ($matches[1] as $index => $hook) { $patterns[] = $matches[0][$index]; $replacements[] = apply_filters($hook, '', $post_content, $post_ID, $post); } } if (count($patterns)) $post_content = str_replace($patterns, $replacements, $post_content); return $post_content; } public function wp_insert_post($post_ID, $post, $update) { global $wpdb; if ($post->post_status != 'publish' || !in_array($post->post_type, $this->options->qc_pseudo_original_random_paragraphs_post_types)) return; if ( $this->options->qc_pseudo_original_random_baidu_included && $this->has_baidu_included($post_ID) ) return; clean_post_cache($post); $post = get_post($post_ID); $values = array( 'back' => $this->get_random_paragraphs($this->options->qc_pseudo_original_random_paragraphs, $post, $post_ID), 'front' => $this->get_random_paragraphs($this->options->qc_pseudo_original_random_paragraphs_front, $post, $post_ID) ); do_action( 'qqworld-collector-log', $this->log_id, 'Random Paragraphs for ID ('.$post_ID.'):, $values', print_r($values, true) ); $post_content = $this->random_paragraphs($post->post_content, $values); $post_content = $this->variable_filter($post_content, $post, $post_ID); if ($post_content != $post->post_content) { $result = $wpdb->update( $wpdb->posts, array( 'post_content' => $post_content ), array( 'ID' => $post_ID ), array( '%s' ), array( '%d' ) ); } } public function get_random_paragraphs($value, $post, $post_ID) { if (empty(trim($value))) return null; $value = preg_replace('/\/\/.*/i', '', $value); $taxonomies = get_object_taxonomies($post->post_type); if (!empty($taxonomies)) { $values = array(); foreach ($taxonomies as $taxonomy) { $pattern = $this->encode_pattern($taxonomy); $preg = preg_match_all('/<tax:'.$pattern.':([\d,]*)>([\s\S]*?)<\/tax:'.$pattern.':([\d,]*)>/', $value, $matches); if ($preg) { foreach ($matches[1] as $index => $match) { if ($match == $matches[3][$index]) { $terms = wp_get_object_terms($post_ID, $taxonomy); if (!empty($terms)) { $ids = explode(',', $match); $childrens = array(); foreach ($ids as $id) { $children = get_term_children($id, $taxonomy); if (!is_wp_error($children) && $children) $childrens = array_merge($childrens, $children); } $ids = array_merge($childrens, $ids); $term_ids = array(); foreach ($terms as $term) $term_ids[] = $term->term_id; if (!empty(array_intersect($ids, $term_ids))) $values[] = $matches[2][$index]; } } } } } if (!empty($values)) $value = implode('<!--s-->', $values); } $values = array(); $preg = preg_match_all('/<(cat|tax):.*?>([\s\S]*?)<\/(cat|tax):.*?>/i', $value, $matches); if ($preg) { $values = array_merge($values, $matches[2]); $value = str_replace($matches[0], '', $value); if (trim($value)) $values[] = $value; $value = implode('<!--s-->', $values); } if ($value) { $value = explode('<!--s-->', $value); $value = array_filter($value, array($this, 'is_not_empty')); foreach ($value as &$v) { $v = trim($v); } $value = $value[array_rand($value)]; } return $value; } public function setting_meta_box() { ?>
	<hr>
	<p>
		<label for="update-random-paragraph"><strong><?php _e('Update Random Paragraph', $this->text_domain); ?></strong></label><br />
		<?php _e('Enabling this option will update the random paragraphs already in the post content.', $this->text_domain); ?>
	</p>
	<?php
 $this->the_switcher(array( 'id' => 'update-random-paragraph', 'name' => 'update-random-paragraph', 'value' => 0 )); } public function scan_random_paragraphs_all() { global $wpdb; extract($_POST); switch ($mode) { case 'wipe': for ($i=0; $i<9999; $i++) { if ( $this->options->qc_pseudo_original_random_baidu_included ) { $sql = "SELECT a.`ID`,a.`post_content` FROM `{$wpdb->posts}` a INNER JOIN `{$wpdb->postmeta}` b ON a.`post_type` IN ('".implode('\',\'', $post_types)."') AND a.`post_content` LIKE '%<!--random-paragraphs-->%' AND a.`ID` = b.`post_id` AND b.`meta_key` = 'baidu_included' AND b.`meta_value` = 1  LIMIT ".($i*1000).",1000"; } else { $sql = "SELECT `ID`,`post_content` FROM `{$wpdb->posts}` WHERE `post_type` IN ('".implode('\',\'', $post_types)."') AND `post_content` LIKE '%<!--random-paragraphs-->%' LIMIT ".($i*1000).",1000"; } $posts = $wpdb->get_results($sql); if (!empty($posts)) { foreach ($posts as $post) { if ( $this->options->qc_pseudo_original_random_baidu_included && !$this->has_baidu_included($post->ID) ) continue; $wpdb->update( $wpdb->posts, array( 'post_content' => preg_replace('/<!--random-paragraphs-->[\s\S]*?<!--\/random-paragraphs-->/i', '', $post->post_content) ), array( 'ID' => $post->ID ), array( '%s' ), array( '%d' ) ); } } else { break; } } $results = array( 'success' => 1, 'msg' => __('Successfully scanned all posts and wiped random paragraphs.', $this->text_domain) ); break; case 'add': default: for ($i=0; $i<9999; $i++) { $sql = "SELECT `ID`,`post_content` FROM `{$wpdb->posts}` WHERE `post_type` IN ('".implode('\',\'', $post_types)."') AND `post_content` NOT LIKE '%<!--random-paragraphs-->%' LIMIT ".($i*1000).",1000"; $posts = $wpdb->get_results($sql); if (!empty($posts)) { foreach ($posts as $post) { if ( $this->options->qc_pseudo_original_random_baidu_included && $this->has_baidu_included($post->ID) ) continue; $post = (object) $post; $values = array( 'back' => $this->get_random_paragraphs($this->options->qc_pseudo_original_random_paragraphs, $post, $post->ID), 'front' => $this->get_random_paragraphs($this->options->qc_pseudo_original_random_paragraphs_front, $post, $post->ID) ); $post_content = $this->random_paragraphs($post->post_content, $values); $post_content = $this->variable_filter($post_content, $post, $post_ID); if ($post_content != $post->post_content) { $result = $wpdb->update( $wpdb->posts, array( 'post_content' => $post_content ), array( 'ID' => $post->ID ), array( '%s' ), array( '%d' ) ); } } } else { break; } } $results = array( 'success' => 1, 'msg' => __('Successfully scanned all posts and added random paragraphs.', $this->text_domain) ); break; } print json_encode($results, JSON_INVALID_UTF8_IGNORE); exit; } } ?>